"""AVIS D'ISSA SUR LA FICHE GEMINI (bouton « 💬 Mon avis sur la fiche » de la page Studio mobile).
Une IA (Gemini, puis Groq ; clés dans les secrets GitHub) lit l'avis, corrige le SCRIPT (tenues, présences) au format du studio,
puis le workflow refait la fiche à partir du script corrigé. La fiche n'est jamais retouchée à la main : tout passe par le script.
Utilisation (GitHub) : ISSUE=N COMMENT_ID=… GH_TOKEN=… GEMINI_API_KEY=… GROQ_API_KEY=… python .github/scripts/avis_fiche.py
Essai local : python .github/scripts/avis_fiche.py --local script.txt "texte de l'avis"   (écrit script_avis.txt à côté)"""
import os, sys, json, re, ast, datetime, subprocess
sys.path.insert(0, os.path.dirname(__file__)); sys.path.insert(0, 'studio')
import relecture as rl   # mêmes appels à Gemini / Groq que le relecteur
import script as sc

N = os.environ.get('ISSUE', ''); LOCAL = '--local' in sys.argv

def nettoyer(b):
    b = re.sub(r'\n+(-{3,}\s*\n+)?_Generated by[\s\S]*$', '', b or '').strip()
    return re.sub(r'(?i)^\s*avis(\s+sur\s+la)?\s+fiche\s*:?\s*', '', b).strip()

def identites():
    src = open('studio/gemini.py', encoding='utf-8').read()
    m = re.search(r'^IDENTITE = (\{.*?^\})', src, re.S | re.M)
    return ast.literal_eval(re.sub(r'#[^\n]*', '', m.group(1))) if m else {}

def tenues_existantes():
    c = json.load(open('studio/assets/catalog.json', encoding='utf-8'))['poses']; t = {}
    for p in c.values():
        if p.get('tenue'): t.setdefault(p['char'], set()).add(p['tenue'])
    return {k: sorted(v) for k, v in t.items()}

def remplacer(s, ancien, nouveau):   # exact d'abord ; sinon on tolère des espaces / retours à la ligne différents (jamais deux endroits)
    if ancien and s.count(ancien) == 1: return s.replace(ancien, nouveau)
    mots = (ancien or '').split()
    if not mots: return None
    m = list(re.finditer(r'\s+'.join(re.escape(w) for w in mots), s))
    return s[:m[0].start()] + nouveau + s[m[0].end():] if len(m) == 1 else None

def verifier(txt):
    """Le script corrigé se lit-il encore ? Chaque [TENUE X: y] a-t-elle sa description (NOUVELLE TENUE) ou des images ?"""
    meta, ev = sc.parse(txt); conn = tenues_existantes(); dites = set()
    for nt in meta.get('new_outfits', []):
        m = re.match(r'\s*(\S+)\s*[—–-]\s*(.+?)\s*(?::|$)', nt)
        if m: dites.add((sc.who(m.group(1)), sc.tenue_id(m.group(2))))
    pb = [f"{e['who']} : tenue « {e['tenue']} » sans description" for e in ev if e.get('type') == 'tenue' and e['tenue'] and (e['who'], e['tenue']) not in dites and e['tenue'] not in conn.get(e['who'], [])]
    return pb

def main():
    if LOCAL:
        chemin, avis = sys.argv[sys.argv.index('--local') + 1:][:2]; fiche = {}
    else:
        chemin = f'demandes/episode_{N}.txt'
        avis = nettoyer(rl.gh(f"/issues/comments/{os.environ['COMMENT_ID']}")['body'])
        f = rl.fichier('fiche_gemini.json'); fiche = json.loads(f) if f else {}
    scr = open(chemin, encoding='utf-8').read()
    if not avis: print('avis vide'); return 1
    titres = '\n'.join(f"Demande {g['g']} : " + ' · '.join(g.get('titres') or []) for g in fiche.get('groupes', [])) or '(pas encore de fiche)'
    sys_txt = open('docs/AVIS_FICHE.md', encoding='utf-8').read()
    user = ('## AVIS D\'ISSA\n' + avis + '\n\n## FICHE ACTUELLE\n' + titres +
            '\n\n## FICHES D\'IDENTITÉ (habits de tous les jours)\n' + '\n'.join(f'{k} : {v}' for k, v in identites().items()) +
            '\n\n## TENUES SPÉCIALES QUI ONT DÉJÀ DES IMAGES\n' + (json.dumps(tenues_existantes(), ensure_ascii=False) or '{}') +
            '\n\n## SCRIPT DE L\'ÉPISODE\n' + scr)
    modele, r, essais = '', None, []
    for tour in range(2):   # 2e tour : on renvoie à l'IA ce qui n'a pas marché
        msg = user + ('' if not essais else '\n\n## TA RÉPONSE PRÉCÉDENTE N\'A PAS MARCHÉ\n' + '\n'.join(essais) + '\nCorrige et renvoie TOUTES les modifications.')
        try: modele, r = rl.gemini(sys_txt, [{'text': msg}])
        except Exception as e:
            print('Gemini :', e); modele, r = rl.groq(sys_txt, msg)
        neuf, faits, essais = scr, [], []
        for m in r.get('modifications') or []:
            x = remplacer(neuf, m.get('ancien', ''), m.get('nouveau', ''))
            if x is None: essais.append(f"« ancien » introuvable ou présent plusieurs fois : {m.get('ancien', '')[:120]}"); continue
            neuf = x; faits.append(m)
        try: essais += verifier(neuf)
        except Exception as e: essais.append(f'le script ne se lit plus : {e}')
        if not essais: break
    if essais: print('reste :', essais)
    ok = faits and neuf != scr and not any('ne se lit plus' in e for e in essais)
    res = {'date': datetime.datetime.utcnow().strftime('%Y-%m-%d %H:%M'), 'avis': avis, 'reponse': r.get('reponse', ''), 'modele': modele,
           'modifications': [{'pourquoi': m.get('pourquoi', ''), 'nouveau': m.get('nouveau', '')} for m in faits] if ok else [], 'restes': essais}
    json.dump(res, open('avis_fiche.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    if LOCAL:
        open(os.path.splitext(chemin)[0] + '_avis.txt', 'w', encoding='utf-8').write(neuf); print(json.dumps(res, ensure_ascii=False, indent=1)); return 0
    if ok:   # le script corrigé devient le script de la demande (texte de la demande + fichier du dépôt)
        open(chemin, 'w', encoding='utf-8').write(neuf)
        iss = rl.gh(f'/issues/{N}'); body = iss.get('body') or ''
        m = re.search(r"(### Script de l'épisode\s*\n+```(?:text)?\n)(.*?)(\n```)", body, re.S)
        body = body[:m.start(2)] + neuf.strip() + body[m.end(2):] if m else "### Script de l'épisode\n\n```text\n" + neuf.strip() + "\n```\n"
        urllib_patch(f'/issues/{N}', {'body': body})
        subprocess.run(['git', 'add', chemin]); subprocess.run(['git', 'commit', '-qm', f'Script de la demande #{N} corrigé selon l\'avis d\'Issa sur la fiche Gemini'])
    lecon = (r.get('lecon') or '').strip()
    if lecon and os.path.exists('technicien/carnet.md'):
        c = open('technicien/carnet.md', encoding='utf-8').read()
        if lecon.lower()[:60] not in c.lower():
            ligne = f"- {res['date'][:10]} · Costumier ({modele.split(' ')[0]}) · {lecon}"
            c = re.sub(r'(## images\n(?:- .*\n)*)', lambda mm: mm.group(1) + ligne + '\n', c, count=1) if '## images' in c else c + '\n## images\n' + ligne + '\n'
            open('technicien/carnet.md', 'w', encoding='utf-8').write(c); subprocess.run(['git', 'add', 'technicien/carnet.md'])
            subprocess.run(['git', 'commit', '-qm', 'Carnet : leçon du costumier (avis d\'Issa sur la fiche)'])
    subprocess.run('git pull -q --rebase --autostash && git push -q', shell=True)
    open('avis_message.txt', 'w', encoding='utf-8').write(
        '💬 **Votre avis est pris en compte** (' + modele + ')\n\n' + res['reponse'] +
        ('\n\n**Script corrigé :**\n' + '\n'.join('- ' + m['pourquoi'] for m in res['modifications']) if ok else '\n\n⚠️ Je n\'ai pas réussi à corriger le script : ' + '; '.join(essais)[:400]) +
        ('\n\n⚠️ Reste à voir : ' + '; '.join(essais)[:300] if ok and essais else ''))
    return 0 if ok else 2

def urllib_patch(path, data):
    import urllib.request
    q = urllib.request.Request('https://api.github.com/repos/' + rl.R + path, data=json.dumps(data).encode(), method='PATCH',
                               headers={'Authorization': 'Bearer ' + os.environ.get('GH_TOKEN', ''), 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json', 'User-Agent': 'sounsouni-studio'})
    urllib.request.urlopen(q, timeout=60).read()

if __name__ == '__main__': sys.exit(main())
